head.script:
/**/(function(){
  var XHTML_NS="http://www.w3.org/1999/xhtml";
  var root=document.querySelector("foreignObject").firstElementChild;
  var origCE=document.createElement.bind(document);
  var origCENS=document.createElementNS.bind(document);
  Object.defineProperty(document,"head",{get:function(){return root.querySelector("head")},configurable:true});
  Object.defineProperty(document,"body",{get:function(){return root.querySelector("body")},configurable:true});
  Object.defineProperty(document,"documentElement",{get:function(){return root},configurable:true});
  document.createElementNS=function(ns,n,o){return (ns==null||ns===XHTML_NS)?origCENS(XHTML_NS,n,o):origCENS(ns,n,o)};
  Object.defineProperty(document,"getElementById",{value:function(id){return root.querySelector('[id="'+String(id).replace(/["\\]/g,'\\$&')+'"]')},configurable:true,writable:true});
  document.getElementsByTagName=function(t){return root.getElementsByTagNameNS(XHTML_NS,t)};
  document.getElementsByTagNameNS=function(ns,t){return root.getElementsByTagNameNS(ns,t)};
  document.getElementsByClassName=function(c){return root.getElementsByClassName(c)};
  var origQS=document.querySelector.bind(document);
  var origQSA=document.querySelectorAll.bind(document);
  document.querySelector=function(s){try{return root.querySelector(s)||origQS(s)}catch(e){return origQS(s)}};
  document.querySelectorAll=function(s){try{var a=root.querySelectorAll(s);return a.length?a:origQSA(s)}catch(e){return origQSA(s)}};
  /* Svelte's static-template instantiation (create_fragment_from_html in its
     internals) builds elements via document.createElement("template").innerHTML
     = "<svg>...</svg>". In a normal HTML document that's fine — the HTML
     fragment parser special-cases a bare <svg> tag and gives it the SVG
     namespace automatically. This document is XML-parsed (a directly-loaded
     .svg always is), and XML fragment parsing has no such special-casing: an
     <svg> tag with no explicit xmlns just inherits the ambient XHTML
     namespace from its <template> parent, silently producing a non-rendering
     "svg" element (confirmed: Lucide icons' <path> children end up correctly
     SVG-namespaced via a separate createElementNS call, but the <svg> root
     around them doesn't, so nothing paints — a plain-string xmlns="..." fix
     doesn't help either: fragment parsing under XML rules doesn't treat an
     attribute string as a live namespace declaration the way full-document
     XML parsing does). Routing "template" specifically to a real, separate
     HTML document (created via createHTMLDocument, genuinely HTML-parsed
     regardless of what the top-level document is) makes its .innerHTML use
     actual HTML fragment parsing, matching what Svelte assumes — nodes
     later move into this document via normal DOM insertion, which adopts
     cross-document nodes automatically. */
  var auxDoc=document.implementation.createHTMLDocument("");
  document.createElement=function(t,o){
    if(typeof t==="string"&&t.toLowerCase()==="template")return auxDoc.createElement("template");
    return typeof t==="string"?origCENS(XHTML_NS,t,o):origCE(t,o);
  };
})();/**/

window.dataLayer = window.dataLayer || [];
function gtag() { dataLayer.push(arguments); }
gtag("js", new Date());
gtag("config", "G-V45JNZYC0T");
